/**
 * When ios.icon points to a .icon (Liquid Glass / Icon Composer) file, Expo's
 * withIosIcons plugin copies the .icon bundle to the native project and sets
 * ASSETCATALOG_COMPILER_APPICON_NAME accordingly — but it does NOT remove any
 * pre-existing AppIcon.appiconset that was generated by an earlier PNG-based
 * prebuild.  That stale directory contains a Contents.json entry with no
 * "filename" key, which causes actool to crash:
 *   "attempt to insert nil object from objects[0]"
 *
 * This plugin runs after withIosIcons and deletes AppIcon.appiconset whenever
 * the iOS icon is a .icon file, since actool gets the icon from Icons.icon
 * directly in that case and AppIcon.appiconset is unreferenced.
 */
const { withDangerousMod } = require('@expo/config-plugins');
const fs = require('fs');
const path = require('path');

module.exports = function withLiquidGlassIconFix(config) {
  return withDangerousMod(config, [
    'ios',
    async (cfg) => {
      const iosIcon = cfg.ios?.icon;
      const isLiquidGlass =
        typeof iosIcon === 'string' && path.extname(iosIcon) === '.icon';

      if (!isLiquidGlass) return cfg;

      const appIconSetPath = path.join(
        cfg.modRequest.platformProjectRoot,
        cfg.modRequest.projectName,
        'Images.xcassets',
        'AppIcon.appiconset'
      );

      if (fs.existsSync(appIconSetPath)) {
        await fs.promises.rm(appIconSetPath, { recursive: true, force: true });
        console.log(
          '[with-liquid-glass-icon-fix] Removed stale AppIcon.appiconset ' +
            '(icon is served by Icons.icon / ASSETCATALOG_COMPILER_APPICON_NAME)'
        );
      }

      return cfg;
    },
  ]);
};
